const root=document,scene=root.querySelector('#scene'),stage=root.querySelector('#design-stage'),dialog=root.querySelector('#section-dialog'),panel=dialog.querySelector('.panel'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
let trigger=null,activeScene='about',galleryIndex=0,shotFrame=0;
const photos=[{src:'assets/demo-football.jpg',title:'Игра в движении',alt:'Демонстрационная фотография юношеского футбольного матча'},{src:'assets/demo-team-v2.jpg',title:'Свои всегда рядом',alt:'Демонстрационная фотография школьной баскетбольной команды'},{src:'assets/court.png',title:'Ещё одна попытка',alt:'Спортивная иллюстрация: мяч и кроссовки на площадке'}];
const memberPlaceholder="<svg viewBox=\"0 0 160 190\" aria-hidden=\"true\"><circle cx=\"80\" cy=\"65\" r=\"29\"/><path d=\"M26 170V150Q28 108 80 108T134 150V170Z\"/></svg>",trophyPlaceholder="<svg viewBox=\"0 0 100 110\" aria-hidden=\"true\"><path d=\"M28 16H72V45Q72 67 50 72Q28 67 28 45Z M28 24H12V38Q12 55 31 55 M72 24H88V38Q88 55 69 55 M50 72V93 M29 98H71\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linejoin=\"round\"/></svg>";
let activeAlbum=null;
const templates={
about:()=>'<article class="club-description"><span class="scene-hand">спорт начинается с нас</span><h2 class="scene-title">Легенда №47</h2><p>Школьный спортивный клуб «Легенда №47» — это объединение учащихся, заинтересованных в развитии спорта в школе.</p><p>Участники занимаются организацией спортивных мероприятий в школе и представляют школьную команду на уровне города и региона.</p><p><strong>Ключевое дело клуба</strong> — организация и проведение школьных летних и зимних Олимпийских игр.</p></article>',
gallery:()=>'<h2 class="scene-title">Каждое событие — свой альбом.</h2><span class="scene-hand">вспоминаем, как это было</span><div class="event-albums">'+photos.map((p,i)=>'<button class="album-card" data-album="'+i+'"><div class="album-cover"><img src="'+p.src+'" alt="'+p.alt+'"><span>АЛЬБОМ 0'+(i+1)+'</span></div><h3>Название мероприятия</h3><p>Будет уточнено · демонстрационный альбом</p><small>Открыть фотографии</small></button>').join('')+'</div><p class="demo-note">Альбомы будут сгруппированы по мероприятиям. Точные названия, даты и фотографии пока не переданы.</p>',
council:()=>'<div class="council-heading"><div><span class="scene-hand">команда — это люди</span><h2 class="team-word" aria-label="Наша команда">'+[...'НАША КОМАНДА'].map(c=>'<span aria-hidden="true">'+(c===' '?'&nbsp;':c)+'</span>').join('')+'</h2></div><button class="scene-button" data-replay>Собрать команду ещё раз</button></div><div class="member-grid">'+[0,1,2].map(i=>'<button class="member-card" data-member="'+i+'"><div class="portrait-placeholder">'+memberPlaceholder+'<span>Место для фотографии</span></div><h3>Фамилия Имя<br>Отчество</h3><p>Участник совета клуба</p></button>').join('')+'</div><p class="demo-note">Каждый участник будет представлен отдельной фотографией и полным ФИО. Имена и портреты пока не добавлены.</p>',
traditions:()=>'<h2 class="scene-title">Так бывает только у своих.</h2><span class="scene-hand">собираем историю по кусочкам</span><div class="collage"><button class="memory" data-memory="0"><img src="assets/demo-football.jpg" alt="Фото-пример игрового момента"><h3>Общий старт</h3><p>С чего начинается наша игра?</p></button><button class="memory" data-memory="1"><img src="assets/demo-team-v2.jpg" alt="Фото-пример команды"><h3>Поддержка своих</h3><p>Голос команды слышно издалека.</p></button><button class="memory" data-memory="2"><img src="assets/court.png" alt="Иллюстрация спортивной площадки"><h3>Передаём эстафету</h3><p>Истории, которые остаются с нами.</p></button></div><p class="tradition-quote">Главное — сколько всего мы сделали вместе.</p><p class="demo-note">Названия — примеры для коллажа. Настоящие традиции клуба предстоит добавить.</p>',
day:()=>'<div class="day-description"><span class="scene-hand">учимся, двигаемся, растём</span><h2 class="scene-title">Школа полного дня</h2><p class="scene-intro">Здесь будет описание школы полного дня: как организована программа, чем занимаются ребята и какую информацию важно знать родителям.</p><p class="scene-intro">Текст дополнит небольшая подборка фотографий, показывающая занятия и повседневную жизнь школы.</p></div><div class="day-photo-row">'+photos.map((p,i)=>'<button class="day-photo" data-photo="'+i+'"><img src="'+p.src+'" alt="'+p.alt+'"><span>Фотография 0'+(i+1)+'</span></button>').join('')+'</div><p class="demo-note">Текст и снимки демонстрируют формат раздела. Материалы программы будут предоставлены школой.</p>',
wins:()=>renderAwards(),
partners:()=>'<div class="partner-names"><span class="scene-hand">спасибо за поддержку!</span><h2 class="scene-title">Наши партнёры</h2>'+[1,2,3].map(i=>'<div class="partner-name"><span>0'+i+'</span><strong>Название организации</strong><small>Будет добавлено</small></div>').join('')+'<p class="demo-note">В разделе будут указаны названия организаций. Список партнёров ожидается от заказчика.</p></div>',
docs:()=>'<div class="doc-sheet"><h2 class="scene-title">Всё по правилам.</h2><p class="scene-intro">Документы клуба — в одном месте.</p>'+['Положение о клубе','План работы клуба','Расписание занятий'].map((t,i)=>'<button class="doc-row" data-doc="'+i+'"><span>0'+(i+1)+'</span><strong>'+t+'</strong><small>Файл ожидается</small></button>').join('')+'<p class="demo-note">Демонстрация списка. Официальные файлы пока не добавлены.</p></div>'};
const labels={about:'01 / НАШ КЛУБ',gallery:'02 / ФОТОГАЛЕРЕЯ',council:'03 / СОВЕТ КЛУБА',traditions:'04 / НАШИ ТРАДИЦИИ',day:'05 / ШКОЛА ПОЛНОГО ДНЯ',wins:'06 / НАШИ ДОСТИЖЕНИЯ',partners:'07 / НАШИ ПАРТНЁРЫ',docs:'08 / ДОКУМЕНТЫ'};
function assemble(){if(reduced.matches)return;scene.querySelectorAll('.team-word span').forEach((letter,i)=>letter.animate([{transform:'translate('+((i%3-1)*60)+'px,'+(i%2?42:-40)+'px) rotate('+(i%2?16:-16)+'deg)',opacity:0},{transform:'none',opacity:1}],{duration:680,delay:i*42,easing:'cubic-bezier(.2,.8,.25,1.2)',fill:'backwards'}));scene.querySelectorAll('.member-card').forEach((card,i)=>card.animate([{transform:'translateY(45px) rotate('+(i%2?9:-9)+'deg)',opacity:0},{transform:'translateY(0) rotate(0)',opacity:1}],{duration:800,delay:240+i*130,easing:'cubic-bezier(.2,.8,.25,1.15)',fill:'backwards'}));}
function selectSection(id,scroll=true){cancelAnimationFrame(shotFrame);activeScene=id;activeAlbum=null;scene.innerHTML=templates[id]();root.querySelector('#stage-kicker').textContent=labels[id];root.querySelectorAll('[data-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.section===id)));if(scroll)stage.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});if(id==='council')assemble();}
root.querySelectorAll('[data-section]').forEach(button=>button.addEventListener('click',()=>selectSection(button.dataset.section)));
function show(html,button){trigger=button;panel.innerHTML=html;dialog.showModal();document.body.style.overflow='hidden';}
function galleryHTML(){const p=photos[galleryIndex];return '<span class="panel-tag">'+(activeAlbum===null?'ФОТО-ПРИМЕР':'АЛЬБОМ 0'+(activeAlbum+1)+' / ПРИМЕР')+'</span><h2 id="panel-title">'+(activeAlbum===null?'Фотография':'Название мероприятия')+'</h2><img class="panel-photo" src="'+p.src+'" alt="'+p.alt+'"><div class="image-dialog-controls"><button data-step="-1">Назад</button><span>'+(galleryIndex+1)+' / '+photos.length+'</span><button data-step="1">Дальше</button></div><p class="hint">Демонстрационное изображение. Настоящие материалы будут добавлены школой.</p>';}
const personTexts=[['Руководитель клуба','Здесь будут имя, фотография, роль в клубе и короткое обращение к ребятам.'],['Педагоги-наставники','Здесь можно познакомить команду с педагогами, направлениями занятий и их подходом к тренировкам.'],['Ученический актив','Здесь появятся ученики, которые предлагают идеи, поддерживают мероприятия и представляют команду.']];
const memoryTexts=[['Общий старт','История традиции может начинаться с первой общей игры. Здесь будут фотографии разных лет и воспоминания участников.'],['Поддержка своих','Какие слова команда слышит с трибун? Здесь можно собрать привычки болельщиков и самые тёплые моменты поддержки.'],['Передаём эстафету','Место для историй о наставничестве и связи поколений: кто помогал новичкам и чему научились друг у друга.']];
const dayTexts=['Время узнавать новое, задавать вопросы и разбираться в сложном вместе.','Время тренироваться, пробовать новые движения и играть в команде.','Время для проектов, творчества и собственных идей.','Время для друзей, общих впечатлений и спокойного отдыха.'];
const winTexts=['Решиться выйти на площадку — уже шаг вперёд.','Замечать свой прогресс и пробовать ещё раз.','Разделить радость с теми, кто был рядом.'];
function throwChalk(){const path=scene.querySelector('.chalk-path'),ball=scene.querySelector('.chalk-ball');if(!path)return;cancelAnimationFrame(shotFrame);const length=path.getTotalLength();path.style.strokeDasharray=length;path.style.strokeDashoffset=length;path.style.opacity=1;const p0=path.getPointAtLength(0);ball.setAttribute('cx',p0.x);ball.setAttribute('cy',p0.y);ball.style.opacity=1;if(reduced.matches){path.style.strokeDashoffset=0;ball.style.opacity=0;return;}const started=performance.now();function tick(now){const t=Math.min(1,(now-started)/1150),point=path.getPointAtLength(t*length);path.style.strokeDashoffset=length*(1-t);ball.setAttribute('cx',point.x);ball.setAttribute('cy',point.y);if(t<1){shotFrame=requestAnimationFrame(tick);}else{ball.style.opacity=0;path.animate([{opacity:1},{opacity:0}],{duration:700,delay:250,fill:'forwards'});}}shotFrame=requestAnimationFrame(tick);}
scene.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.hasAttribute('data-replay')){assemble();return;}
if(b.hasAttribute('data-fan')){const fan=scene.querySelector('.fan'),open=fan.dataset.open!=='true';fan.dataset.open=String(open);b.setAttribute('aria-expanded',String(open));b.textContent=open?'Собрать стопку':'Разложить фотографии';return;}
if(b.hasAttribute('data-photo')){galleryIndex=Number(b.dataset.photo);show(galleryHTML(),b);return;}
if(b.hasAttribute('data-person')){const t=personTexts[Number(b.dataset.person)];show('<span class="panel-tag">ПРИМЕР КАРТОЧКИ</span><h2 id="panel-title">'+t[0]+'</h2><p>'+t[1]+'</p><p class="hint">Имена и состав клуба пока не заданы.</p>',b);return;}
if(b.hasAttribute('data-memory')){const t=memoryTexts[Number(b.dataset.memory)];show('<span class="panel-tag">ПРИМЕР ИСТОРИИ</span><h2 id="panel-title">'+t[0]+'</h2><p>'+t[1]+'</p>',b);return;}
if(b.hasAttribute('data-day')){scene.querySelectorAll('[data-day]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));scene.querySelector('.day-copy').textContent=dayTexts[Number(b.dataset.day)];return;}
if(b.hasAttribute('data-win')){scene.querySelectorAll('[data-win]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));scene.querySelector('.win-story').textContent=winTexts[Number(b.dataset.win)];scene.querySelector('.chalk-path').getAnimations().forEach(a=>a.cancel());throwChalk();return;}
if(b.hasAttribute('data-doc')){show('<span class="panel-tag">ДОКУМЕНТЫ</span><h2 id="panel-title">'+b.querySelector('strong').textContent+'</h2><p>Официальный файл пока не добавлен. В готовом интерфейсе здесь можно будет прочитать и скачать документ.</p>',b);}});
panel.addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(!b)return;const step=b.dataset.step;galleryIndex=(galleryIndex+Number(step)+photos.length)%photos.length;panel.innerHTML=galleryHTML();panel.querySelector('[data-step="'+step+'"]').focus();});
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';trigger?.focus();});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
selectSection('about',false);
if('IntersectionObserver' in window){const observe=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){if(activeScene==='council')assemble();observe.disconnect();}},{threshold:.25});observe.observe(stage);}

scene.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.hasAttribute('data-album')){activeAlbum=Number(b.dataset.album);scene.innerHTML='<div class="album-top"><button class="album-back" data-albums>Все мероприятия</button><span>АЛЬБОМ 0'+(activeAlbum+1)+'</span></div><div class="gallery-head"><div><h2 class="scene-title">Название мероприятия</h2><span class="scene-hand">подписи и дата появятся здесь</span></div><button class="scene-button" data-fan aria-expanded="false">Разложить фотографии</button></div><div class="fan" data-open="false">'+photos.map((p,i)=>'<button class="fan-card" style="--i:'+(i-1)+'" data-photo="'+i+'"><img src="'+p.src+'" alt="'+p.alt+'"><span>Кадр 0'+(i+1)+'</span></button>').join('')+'</div><p class="demo-note">Три кадра показывают работу альбома. Название мероприятия и реальные фотографии пока не добавлены.</p>';return;}
if(b.hasAttribute('data-albums')){selectSection('gallery',false);return;}
if(b.hasAttribute('data-member')){show('<span class="panel-tag">УЧАСТНИК СОВЕТА КЛУБА</span><div class="member-dialog"><div class="portrait-placeholder">'+memberPlaceholder+'<span>Место для фотографии</span></div><div><h2 id="panel-title">Фамилия Имя Отчество</h2><p>Здесь будут фотография и полное имя участника совета клуба.</p><p class="hint">Персональные данные пока не переданы.</p></div></div>',b);return;}
if(b.hasAttribute('data-award')){awardIndex=Number(b.dataset.award);dialog.classList.add('awards-dialog');show(awardPanelHTML(awardIndex),b);return;}
});

let awardIndex=0;
function moveAward(step){
  awardIndex=(awardIndex+step+clubAwards.length)%clubAwards.length;
  panel.innerHTML=awardPanelHTML(awardIndex);
  panel.scrollTop=0;
  panel.querySelector('[data-award-step="'+step+'"]').focus({preventScroll:true});
}
panel.addEventListener('click',e=>{const button=e.target.closest('[data-award-step]');if(button)moveAward(Number(button.dataset.awardStep));});
dialog.addEventListener('keydown',e=>{if(!dialog.classList.contains('awards-dialog')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveAward(e.key==='ArrowRight'?1:-1);}});
dialog.addEventListener('close',()=>dialog.classList.remove('awards-dialog'));
if(location.hash==='#wins')selectSection('wins');
